#include <stdio.h>
#include <stdlib.h>

static int abs_int(int x)
{
    return x < 0 ? -x : x;
}

int cmp(const void *pa, const void *pb)
{
    int a = *(const int *)pa;
    int b = *(const int *)pb;
    int aa = abs_int(a);
    int bb = abs_int(b);

    if (aa != bb)
        return aa < bb ? -1 : 1;
    if (a == b)
        return 0;
    return a < b ? -1 : 1;
}

int main(void)
{
    int n, i;
    int *a;

    if (scanf("%d", &n) != 1 || n <= 0 || n > 100)
        return 0;
    a = (int *)malloc((size_t)n * sizeof(int));
    if (a == NULL)
        return 1;
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);

    qsort(a, (size_t)n, sizeof(int), cmp);

    for (i = 0; i < n; i++)
        printf("%d%c", a[i], i < n - 1 ? ' ' : '\n');
    free(a);
    return 0;
}

