int squeeze(char *s)
{
    char *p = s;
    char *q = s;

    while (*p != '\0') {
        if (*p != ' ')
            *q++ = *p;
        p++;
    }
    *q = '\0';
    return (int)(q - s);
}

int main(void)
{
    char s[200];
    char *p;
    int n;

    if (fgets(s, sizeof(s), stdin) == NULL)
        return 0;

    p = s;
    while (*p != '\0' && *p != '\n')
        p++;
    *p = '\0';

    n = squeeze(s);
    printf("%s\n%d\n", s, n);
    return 0;
}

